import React from 'react';
import { injectEfCss } from '../forms/Button.jsx';

const CSS = `
@keyframes ef-spinner{to{transform:rotate(360deg)}}
.ef-spinner{display:inline-block;flex:none;color:var(--text-muted);animation:ef-spinner .7s linear infinite}
`;

export const Spinner = React.forwardRef(function Spinner(
  { size = 16, label, className, width, height, ...props },
  ref,
) {
  injectEfCss('ef-css-spinner', CSS);
  return (
    <svg
      ref={ref}
      role="status"
      aria-label={label || 'Loading'}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      width={width ?? size}
      height={height ?? size}
      className={`ef-spinner${className ? ' ' + className : ''}`}
      {...props}
    >
      <path d="M21 12a9 9 0 1 1-6.219-8.56" />
    </svg>
  );
});

export interface SpinnerProps extends React.SVGProps<SVGSVGElement> {
  /** Meridian legacy pixel-size helper. @default 16 */
  size?: number;
  /** Meridian legacy accessible-label alias. */
  label?: string;
}
export declare const Spinner: React.ForwardRefExoticComponent<SpinnerProps & React.RefAttributes<SVGSVGElement>>;
